def txt(i):
 f=evdir/f'{i}.live.txt'
 if not f.exists():f=evdir/f'{i}.raw.txt'
 return re.sub(r'\s+',' ',f.read_text()).strip()
def evidence(i,q,n,provision,dates,last=False):
 t=txt(i);pos=t.rfind(q) if last else t.find(q)
 assert pos>=0,(i,q)
 f=fetch[i] if fetch[i]['status']=='success' else raw[i]
 return {'url':f'https://vbpl-bientap-gateway.moj.gov.vn/api/qtdc/public/doc/{i}','document_number':json.load(open(evdir/f'{i}.raw.json'))['docNum'],'provision':provision,'as_of':dates,'quote':t[pos:pos+n],'source_tier':'official','accessed_at':f.get('accessed_at',now),'snapshot_path':f.get('path',f.get('snapshot_path')),'snapshot_sha256':f.get('sha256'),'source_mode':'live_api_unwrapped_data.documentContent.content' if fetch[i]['status']=='success' else 'official_raw_snapshot; live API HTTP400'}
def label(d,side='a',**changes):
 src=d['label_'+side]; z={k:src.get(k,'') for k in ['q1','q1_reason','q2','q2_reason','q3','q3_reason','q4','q4_reason']};z.update(changes);z['verdict']='dat' if [z[x] for x in ['q1','q2','q3','q4']]==['dung','co','co','khong'] else 'khong_dat';z.update(guideline_version='4.0',quote='',search_log='',note='',evidence_status='sufficient');return z
